extern "C" bool func_08033B24(HarvestSpriteActor * state)
{
    u32 entry_offset = state->entry_index;
    HarvestSpriteWorkTarget const * entry = state->entries;
    entry_offset <<= 3;
    entry = (HarvestSpriteWorkTarget const *)((u8 const *)entry + entry_offset);
    if ((((u8 const *)entry)[0] << 28) != 0)
    {
        return false;
    }

    GameObject * game_object = state->game_object;
    EntityUiHarvestSpriteResult result;
    Location location = state->AEntity::GetLocation();
    HarvestSprite::Task task = state->harvest_sprite->GetCurrentTask();
    func_080330F4(&result, state->farm, game_object, &location, task,
                  state->entries);

    EntityUiHarvestSpriteResult * result_pointer = &result;
    u32 value = 0;
    if ((result_pointer->flags << 28) == 0)
    {
        value = 1;
    }
    return value;
}

extern "C" void ClearEntityUiUnknownFlag41(HarvestSpriteActor * state)
{
    state->unk_41 = 0;
}

extern "C" void SetEntityUiResource(HarvestSpriteActor * state,
    u32 table_index, u32 first_value, u32 second_value)
{
    if (static_cast<HarvestSpriteController *>(state->unk_10.Get()) != nullptr)
        InitializeEntityUiResourceFromTable(static_cast<HarvestSpriteController *>(state->unk_10.Get()),
            table_index, first_value, second_value);
}

