extern "C" void InitializeEntityUiResourceFromTable(HarvestSpriteController * state,
                               u32 table_index, u32 first_value,
                               u32 second_value)
{
    u16 const * table = gUnk_080F14F0;
    u16 resource_id = table[table_index];
    ResolveIndexedResourceHandle(&state->resource_sprite.handle, resource_id);

    state->resource_sprite.unk_3C = 1;
    state->resource_sprite.unk_3E = 0;
    state->resource_sprite.unk_3F = 1;
    state->resource_x = first_value;
    state->resource_y = second_value;
    state->duration = 0x3C;
}

extern "C" u32 GetEntityUiResourceTableIndex(HarvestSpriteActor const * state)
{
    return state->entry_index;
}

extern "C" HarvestSpriteController * GetEntityUiResourceSetup(HarvestSpriteActor const * state)
{
    return static_cast<HarvestSpriteController *>(state->unk_10.Get());
}

extern "C" void SetSelectedEntityUiResource(HarvestSpriteActor * state,
    u32 first_value, u32 second_value)
{
    SetEntityUiResource(state, state->entry_index, first_value, second_value);
}
